import { buildKit, evaluateProduct, scoreProduct, money, SLOT_LABELS, defaultProfile } from './engine.js';
import { createSelfieExperience } from './selfie-ui.js';
import { MAKEUP_CATEGORIES, FACE_REGIONS, categoryLabel, filterCatalog, validSavedLooks } from './beauty-library.js';
import { createLookbook } from './lookbook.js';
import { createStyleGuideUI } from './style-guide-ui.js';
import { applyStyleGuide } from './style-guides.js';

const $ = s => document.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons = {
  camera:'M4 7h4l2-3h4l2 3h4v14H4Z M16 14a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',
  drop:'M12 3C9 8 5 11 5 16a7 7 0 0 0 14 0c0-5-4-8-7-13Z M9 16a3 3 0 0 0 3 3',
  home:'m3 10 9-7 9 7 M5 9v12h14V9 M9 21v-7h6v7',
  bag:'M5 7h14l1 14H4L5 7Z M8 8V6a4 4 0 0 1 8 0v2',
  grid:'M4 4h6v6H4z M14 4h6v6h-6z M4 14h6v6H4z M14 14h6v6h-6z',
  user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z M4 21v-2a8 8 0 0 1 16 0v2',
  arrow:'M4 12h16 m-6-6 6 6-6 6', back:'M20 12H4 m6-6-6 6 6 6',
  check:'m5 12 4 4L19 6', heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',
  sparkle:'m12 2 2.7 7.3L22 12l-7.3 2.7L12 22l-2.7-7.3L2 12l7.3-2.7L12 2Z',
  leaf:'M20 3C7 2 2 8 5 15s14 8 15-12Z M5 20 16 8',
  coin:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z M15 8h-4a2 2 0 0 0 0 4h2a2 2 0 0 1 0 4H9 M12 6v12',
  shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z m-4 9 3 3 5-6',
  search:'M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0Z m-2 5 6 6',
  close:'m6 6 12 12 M18 6 6 18',up:'m6 15 6-6 6 6',down:'m6 9 6 6 6-6',
  book:'M12 5C8 2 3 4 3 4v16s5-2 9 1c4-3 9-1 9-1V4s-5-2-9 1Z M12 5v16',
  external:'M14 3h7v7 m0-7-11 11 M10 3H3v18h18v-7', clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z M12 7v5l3 2',
};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name] || icons.sparkle}"/></svg>`;
const goalLabels = {quick_easy:'Quick & easy',hydration_comfort:'Hydration & comfort',less_shine:'Less shine',natural_makeup:'Natural makeup',longer_wear:'Longer wear'};
const skinLabels = {dry_tight:'Dry or tight',oily_shiny:'Oily or shiny',mixed:'A little of both',comfortable:'Comfortable',unknown:'Not sure'};
const allSlots = ['cleanser','moisturizer','daytime_sunscreen','lip','cheek','eyes','base','toner','serum','remover'];
const shortSlots = {cleanser:'Cleanser',moisturizer:'Moisturizer',daytime_sunscreen:'Sunscreen',lip:'Lip color',cheek:'Cheek color',eyes:'Eyes',base:'Foundation / base',toner:'Toner / essence',serum:'Serum',remover:'Makeup remover'};
const slotLabel = s => shortSlots[s] || SLOT_LABELS[s] || s;
const stepLabels = ['Your everyday kit','Budget & shopping','Keep your favorites','Goals & routine','Skin & comfort','Personal preferences','Review your plan'];
const navs = [['selfie','camera','Selfie'],['kit','bag','My kit'],['explore','grid','Explore'],['looks','sparkle','Looks'],['profile','user','You']];
const storageKey = 'dewdrop.v1';
let catalog, products, evidence, productImages, styleLibrary, lookbook, styleGuides, styleUI, state, draft, result, selfie, step=0, filter='all', search='', brand='', makeupCategory='', faceRegion='', catalogLimit=24, savedOnly=false, toastTimer;
try { state = JSON.parse(localStorage.getItem(storageKey) || '{}'); } catch { state = {}; }
state.favorites = Array.isArray(state.favorites) ? state.favorites : [];
state.savedLooks = Array.isArray(state.savedLooks) ? state.savedLooks : [];
const productPrice = p => typeof p.price_usd === 'number' && Number.isFinite(p.price_usd) ? money(Math.round(p.price_usd * 100)) : 'Price not verified';
function newProfile(){ return {...defaultProfile(), scope:'both', slots:['cleanser','moisturizer','daytime_sunscreen','lip'],budgetCents:null,reserveCents:0,country:'United States',ownedSlots:[],goals:[],routineTime:'5_minutes',itemCap:5,reactionHistory:'',avoidedIngredients:[],reactedProductIds:[],mandatoryRequirements:[],preferredRequirements:[],skinFeel:'unknown',texture:'unknown',makeupSkill:'unknown',coverage:'unknown',finish:'unknown',colorFamily:'unknown',eyeEffect:'unknown',wear:'unknown',simpleApplication:false,selectedShades:{},swaps:{}}; }
draft = {...newProfile(), ...(state.draft || state.profile || {})};
const save = () => { state.draft=draft; try { localStorage.setItem(storageKey,JSON.stringify({...state,draft})); } catch { toast('Device storage is unavailable. Keep this session open to retain your plan.'); } };
function toast(message){ clearTimeout(toastTimer); $('#toast').textContent=message; $('#toast').classList.add('show'); toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500); }
function nav(page){ if (location.hash === '#'+page) render(); else location.hash=page; }
function route(){ const parts=(location.hash.slice(1)||'home').split('/'); step=Math.min(6,Math.max(0,Number(parts[1])||0)); return parts[0]; }
const brandIcon = '<img class="brand-logo" src="icon.svg" width="32" height="32" alt="">';
function brandmark(){ return `<span class="brand">${brandIcon}dewdrop</span>`; }
function shell(content,page){const activePage=page==='recommendations'?'selfie':page==='guides'?'looks':page;return `<header class="topbar"><button class="brand" data-nav="home" aria-label="Dewdrop home">${brandIcon}dewdrop</button><nav class="desktop-nav" aria-label="Main">${navs.map(([id,ic,label])=>`<button class="nav-button ${id==='selfie'?'selfie-nav ':''}${activePage===id?'active':''}" data-nav="${id}" ${activePage===id?'aria-current="page"':''}>${icon(ic)}${label}</button>`).join('')}</nav><div class="row"><span class="offline">Your beauty starts with you</span><button class="avatar" data-nav="profile" aria-label="Your profile" ${page==='profile'?'aria-current="page"':''}>D</button></div></header><main class="main" id="main">${content}</main><footer class="footer">${brandmark()}<span>Your selfie. Your Korean beauty map.</span><span>U.S. catalog · USD · October 2026</span></footer><nav class="bottom-nav" aria-label="Main mobile">${navs.map(([id,ic,label])=>`<button class="${id==='selfie'?'selfie-nav ':''}${activePage===id?'active':''}" data-nav="${id}" ${activePage===id?'aria-current="page"':''}><span class="nav-icon">${icon(ic)}</span>${label}</button>`).join('')}</nav>`; }
function productImage(p,{eager=false}={}){const photo=productImages?.[p.id];const available=typeof photo?.src==='string'&&/^assets\/products\/[\w.-]+$/.test(photo.src);return `<div class="product-photo${available?'':' is-unavailable'}">${available?`<img src="${esc(photo.src)}" alt="${esc(photo.alt||`${p.brand} ${p.product_name} product packaging`)}" loading="${eager?'eager':'lazy'}" decoding="async">`:''}<div class="product-photo-unavailable" ${available?'hidden':''}><span>${esc(p.brand)}</span><span>Product photo unavailable</span></div></div>`;}
function heroPhotos(){return styleUI.hero();}
function productCard(p){const n=Number(p.id.split('-')[1]);return `<article class="product-card"><div class="product-art art-${n%4+1}">${productImage(p)}<button class="icon-btn ${state.favorites.includes(p.id)?'saved':''}" data-save="${p.id}" aria-label="${state.favorites.includes(p.id)?'Unsave':'Save'} ${esc(p.product_name)}" aria-pressed="${state.favorites.includes(p.id)}">${icon('heart')}</button></div><div class="product-info"><p class="eyebrow">${esc(p.brand)}</p><button class="product-title" data-detail="${p.id}">${esc(p.product_name)}</button><p class="category">${esc(p.makeup_category ? categoryLabel(p.makeup_category) : p.category)}</p><div class="row between"><span class="price">${productPrice(p)}</span><span class="pill ${p.budget_tier==='Premium'?'purple':''}">${esc(p.budget_tier)}</span></div></div></article>`;}
function home(){return `<div class="home-intro row between"><span>Start with you.</span><span class="pill">Your personal K-beauty map</span></div><section class="hero"><div class="hero-copy"><div class="eyebrow">${icon('camera')} A selfie is your starting point</div><h1>Your face.<br>Your beauty <em>map.</em></h1><p>Take a selfie to discover styles and product ideas on your own photo. Tap your brows, cheeks, or lips to get closer, then refine the picks with what you want.</p><div class="hero-selfie-actions"><button class="btn" data-nav="selfie">${icon('camera')} Take a selfie ${icon('arrow')}</button><button class="text-btn" data-nav="recommendations">${state.profile?'Open my beauty map':'Explore without a photo'}</button></div><div class="hero-foot">${icon('check')} Photo-led suggestions · Yours to edit</div></div>${heroPhotos()}</section><div class="trust-strip"><div>${icon('camera')}<div><strong>See it on your selfie</strong><span>Your features, mapped for you</span></div></div><div>${icon('sparkle')}<div><strong>A few ideas at a time</strong><span>Tap to see the style and products</span></div></div><div>${icon('book')}<div><strong>Make every pick yours</strong><span>Your goals, comfort, and budget</span></div></div></div><section><div class="section-head"><div><h2>Meet your everyday essentials</h2><p>A few favorites from our ${products.length}-product beauty shelf.</p></div><button class="text-btn" data-nav="explore">Explore all ${icon('arrow')}</button></div><div class="product-grid">${['kbeauty-001','kbeauty-004','kbeauty-006','kbeauty-047'].map(id=>productCard(products.find(p=>p.id===id))).join('')}</div></section>${styleUI.teaser()}${lookbook.teaser()}<section class="quiet-banner">${icon('sparkle')}<div><h3>Your photo starts the conversation.</h3><p>Your goals, preferences, and product history help refine what comes next.</p></div><button class="text-btn" data-start>Edit my preferences ${icon('arrow')}</button></section>`;}
function filteredProducts(){return filterCatalog(products,evidence,{search,brand,kind:filter,category:makeupCategory,region:faceRegion,savedOnly,favorites:state.favorites});}
function explore(){return `<div class="page-top"><p class="eyebrow">A shelf worth exploring</p><h1>Find your next favorite.</h1><p>${products.length} products. ${catalog.brand_count} Korean beauty brands. Skincare, makeup, and room for your own kind of routine.</p></div><div class="catalog-look-link row between"><span>Pick a makeup direction or a skincare routine for a different product edit.</span><button class="text-btn" data-nav="guides">Explore styles & routines ${icon('arrow')}</button></div><div class="filterbar"><label class="search">${icon('search')}<input id="search" type="search" value="${esc(search)}" placeholder="Search products, brands, or artists" aria-label="Search catalog"></label><button class="chip ${savedOnly?'active':''}" data-saved-filter aria-pressed="${savedOnly}">Saved (${state.favorites.length})</button><select id="brand-filter" class="form-input brand-filter" aria-label="Filter brand"><option value="">All brands</option>${[...new Set(products.map(p=>p.brand))].sort().map(b=>`<option ${brand===b?'selected':''}>${esc(b)}</option>`).join('')}</select></div><div class="filterbar">${[['all','All products'],['skincare','Skincare'],['makeup','Makeup'],['kpop','K-pop connections']].map(([v,l])=>`<button class="chip ${filter===v?'active':''}" data-filter="${v}" aria-pressed="${filter===v}">${l}</button>`).join('')}<span class="saved-count" id="result-count" aria-live="polite"></span></div>${filter!=='skincare'?`<div class="filterbar catalog-subfilters"><label>Makeup type<select id="makeup-category" class="form-input" aria-label="Filter makeup type"><option value="">All types</option>${MAKEUP_CATEGORIES.map(c=>`<option value="${c.id}" ${makeupCategory===c.id?'selected':''}>${c.label} (${products.filter(p=>p.makeup_category===c.id).length})</option>`).join('')}</select></label><label>Face region<select id="face-region" class="form-input" aria-label="Filter product face region"><option value="">All regions</option>${FACE_REGIONS.map(r=>`<option value="${r.id}" ${faceRegion===r.id?'selected':''}>${r.label}</option>`).join('')}</select></label>${makeupCategory||faceRegion||brand||search?'<button class="text-btn" data-clear-catalog-filters>Clear filters</button>':''}</div>`:''}<div id="catalog-grid" class="product-grid"></div><div id="catalog-more" class="catalog-more"></div><p class="small muted" style="margin-top:22px">Prices are research snapshots, before shipping and tax. Open a product for its exact size, shade, and photo source.</p>`;}
function updateGrid(){if(!$('#catalog-grid'))return;const list=filteredProducts();$('#catalog-grid').innerHTML=list.slice(0,catalogLimit).map(productCard).join('')||'<p class="no-results">No products match these filters. Try another brand or search.</p>';$('#result-count').textContent=`${list.length} products`;$('#catalog-more').innerHTML=list.length>catalogLimit?`<button class="btn secondary" data-more-products>Show more products (${Math.min(catalogLimit,list.length)} of ${list.length})</button>`:'';}
function options(field, choices){return `<div class="option-grid">${choices.map(([value,label,sub])=>`<button class="option ${draft[field]===value?'selected':''}" data-answer="${field}" data-value="${value}" aria-pressed="${draft[field]===value}"><strong>${label}</strong>${sub?`<span>${sub}</span>`:''}</button>`).join('')}</div>`;}
function select(field,label,choices,note=''){return `<label class="field"><span>${label}</span><select data-field="${field}">${choices.map(([v,l])=>`<option value="${v}" ${draft[field]===v?'selected':''}>${l}</option>`).join('')}</select>${note?`<small>${note}</small>`:''}</label>`;}
function chips(field,choices){return `<div class="chip-row">${choices.map(([v,l])=>`<button class="chip ${(draft[field]||[]).includes(v)?'active':''}" data-toggle="${field}" data-value="${v}" aria-pressed="${(draft[field]||[]).includes(v)}">${l}</button>`).join('')}</div>`;}
function flow(){let content='';const makeup=draft.slots.some(s=>['lip','cheek','eyes','base'].includes(s));const skincare=draft.slots.some(s=>['cleanser','moisturizer','daytime_sunscreen','toner','serum'].includes(s));
  if(step===0)content=`<h1>What belongs in your kit?</h1><p class="flow-subtitle">A fresh start or a finishing touch. Choose what you’d like help with.</p>${options('scope',[['skincare','Skincare','A simple daily foundation'],['makeup','Makeup','A little everyday color'],['both','A bit of both','Prep, protect, and finish'],['help_choose','Help me choose','Start with three essentials']])}<div class="field"><span>Your proposed products</span>${chips('slots',allSlots.map(s=>[s,slotLabel(s)]))}<small>Tap to add or remove. Extras stay off until you choose them.</small></div><div class="hint">We’ll keep one product per selected category. You can set their priority before finishing.</div>`;
  if(step===1)content=`<h1>A little plan for your budget.</h1><p class="flow-subtitle">This is your budget for all new products together.</p><div class="fields-two"><label class="field"><span>Total budget · USD</span><input id="budget-input" data-money="budgetCents" type="number" min="0" step="0.01" inputmode="decimal" value="${draft.budgetCents===null?'':(draft.budgetCents/100).toFixed(2)}" placeholder="e.g. 75.00"><small>Leave blank for an unpriced preview.</small></label><label class="field"><span>Set aside for tax & shipping</span><input data-money="reserveCents" type="number" min="0" step="0.01" inputmode="decimal" value="${draft.reserveCents?(draft.reserveCents/100).toFixed(2):''}" placeholder="Optional"><small>A reserve you choose, not a fee estimate.</small></label></div>${select('country','Where are you shopping?',[['United States','United States · USD'],['Other','Another country']])}<div class="hint">${draft.country==='United States'?'Our catalog has U.S. prices and selected product versions. Final prices, stock, tax, and shipping still need checking at the shop.':'This first catalog covers the U.S. only. You can browse, but a kit for another country will stay pending.'}</div>`;
  if(step===2)content=`<h1>Keep what you already love.</h1><p class="flow-subtitle">Which products do you own and want to keep using?</p><div class="field">${chips('ownedSlots',[...new Set([...draft.slots,'remover'])].map(s=>[s,slotLabel(s)]))}</div><div class="hint">Retained products cost $0 in your new kit and count toward its item limit. Keeping a product doesn’t confirm tolerance or compatibility.</div><label class="field"><span>Names or notes (optional)</span><textarea data-field="ownedNotes" placeholder="For example: keep my current cleanser">${esc(draft.ownedNotes||'')}</textarea><small>These notes stay on your device.</small></label>`;
  if(step===3)content=`<h1>What makes a good morning?</h1><p class="flow-subtitle">Choose up to two priorities. Your first choice comes first.</p><div class="field">${chips('goals',Object.entries(goalLabels))}<small>${draft.goals.map((g,i)=>`${i+1}. ${goalLabels[g]}`).join(' · ')||'No priorities selected yet.'}</small></div><div class="field"><span>How much time would you like for your routine?</span>${options('routineTime',[['3_minutes','About 3 minutes','Suggest 3 daily products'],['5_minutes','About 5 minutes','Suggest 5 daily products'],['10_minutes','About 10 minutes','Suggest 7 daily products'],['help_start_small','Start small','Suggest 3 daily products']])}</div><label class="field"><span>Daily product limit</span><input data-number="itemCap" type="number" min="1" max="12" step="1" value="${draft.itemCap}"><small>These are editable product counts, not promises about application time.</small></label>`;
  if(step===4)content=`<h1>Let’s get to know your skin.</h1><p class="flow-subtitle">Add how your skin feels and your product history to refine the suggestions from your selfie.</p>${skincare?select('skinFeel','How does your skin usually feel?',Object.entries(skinLabels)):''}<div class="field"><span>Have products irritated your skin before?</span>${options('reactionHistory',[['no','No known reactions','No specific history to add'],['yes','Yes, I have details','Add ingredients or a product'],['unsure','I’m not sure','Keep recommendations pending']])}</div><label class="field"><span>Ingredients you need to avoid</span><input data-list="avoidedIngredients" value="${esc(draft.avoidedIngredients.join(', '))}" placeholder="Separate ingredients with commas"><small>The catalog has selected ingredients, not complete formulas. Products with unverified exclusions remain pending.</small></label>${draft.reactionHistory==='yes'?`<label class="field"><span>Products that caused a reaction</span><select id="reaction-product"><option value="">Choose a catalog product to exclude</option>${products.map(p=>`<option value="${p.id}">${esc(p.brand+' · '+p.product_name)}</option>`).join('')}</select></label><div class="field">${chips('reactedProductIds',draft.reactedProductIds.map(id=>[id,esc(products.find(p=>p.id===id)?.product_name||id)]))}</div><label class="field"><span>Anything else about the reaction?</span><textarea data-field="reactionNotes" placeholder="Add the product and what happened. Unresolved details keep suggestions pending.">${esc(draft.reactionNotes||'')}</textarea></label>`:''}`;
  if(step===5)content=`<h1>The little things you like.</h1><p class="flow-subtitle">Skip anything you’re unsure about. You can change it later.</p><div class="fields-two">${select('texture','Preferred texture',[['unknown','No preference'],['lightweight','Lightweight'],['rich','Rich & comforting'],['nonsticky','Not sticky']])}${makeup?select('makeupSkill','Your makeup experience',[['unknown','Not sure'],['new','Completely new'],['basics','Know the basics'],['comfortable','Comfortable']]):''}</div>${makeup?`<div class="fields-two">${select('finish','Preferred finish',[['unknown','No preference'],['dewy','Dewy / glowy'],['matte','Matte'],['natural','Natural']])}${select('wear','Wear preference',[['unknown','No preference'],['long_wear','Longer wear'],['easy_removal','Easy removal']])}</div>${draft.slots.some(s=>['lip','cheek'].includes(s))?select('colorFamily','Lip or cheek color family',[['unknown','No preference'],['pink','Pink'],['rose','Rose'],['coral','Coral'],['red','Red'],['nude','Nude'],['berry','Berry']]):''}${draft.slots.includes('eyes')?select('eyeEffect','Preferred eye effect',[['unknown','No preference'],['definition','Definition'],['volume','Volume'],['length','Length'],['soft_color','Soft color']]):''}${draft.slots.includes('base')?`${select('coverage','Preferred coverage',[['unknown','Not sure'],['spot_only','Just a few spots'],['light_all_over','Light coverage all over'],['more_coverage','More coverage']])}<div class="field"><span>Choose a supported exact shade (optional)</span><small>Select only if you want this specific product and shade. Shade numbers don’t translate across brands; this isn’t a shade match.</small>${products.filter(p=>evidence[p.id]?.slots.includes('base')&&evidence[p.id]?.exactShade).map(p=>`<label class="checkline"><input type="checkbox" data-shade="${p.id}" ${draft.selectedShades[p.id]?'checked':''}><span>${esc(p.brand+' · '+p.product_name)}</span></label>`).join('')}</div>`:''}`:''}<div class="fields-two">${requirementSelect('fragrance_free','Fragrance-free')}${requirementSelect('vegan','Vegan')}</div><label class="checkline" style="margin-top:20px"><input type="checkbox" data-boolean="simpleApplication" ${draft.simpleApplication?'checked':''}><span>I prefer simple application with no extra tools.</span></label><div class="hint">A must-have filters products. A preference only helps break ties when the exact product claim is verified.</div>`;
  if(step===6)content=`<h1>Your kit, your call.</h1><p class="flow-subtitle">One last look before we put your plan together.</p><dl class="review-grid"><div><dt>Total budget</dt><dd>${draft.budgetCents===null?'Unpriced preview':money(draft.budgetCents)}</dd></div><div><dt>Tax & shipping reserve</dt><dd>${money(draft.reserveCents)}</dd></div><div><dt>Daily product limit</dt><dd>${draft.itemCap} products, including kept items</dd></div><div><dt>Your priorities</dt><dd>${draft.goals.map(g=>goalLabels[g]).join(', ')||'Basic options by eligibility & cost'}</dd></div><div><dt>Skin feel</dt><dd>${skinLabels[draft.skinFeel]||'Not selected'}</dd></div><div><dt>Shopping region</dt><dd>${esc(draft.country)} · USD</dd></div></dl><div class="field"><span>Product priority</span><small>If everything won’t fit, the products highest on this list come first. Move them to make this your own.</small>${draft.slots.map((s,i)=>`<div class="slot-row"><span class="slot-number">${String(i+1).padStart(2,'0')}</span><span class="slot-name">${slotLabel(s)} ${draft.ownedSlots.includes(s)?'<span class="pill">Keeping mine</span>':''}</span><button class="icon-btn" data-move="${s}" data-direction="-1" ${i===0?'disabled':''} aria-label="Move ${slotLabel(s)} up">${icon('up')}</button><button class="icon-btn" data-move="${s}" data-direction="1" ${i===draft.slots.length-1?'disabled':''} aria-label="Move ${slotLabel(s)} down">${icon('down')}</button></div>`).join('')}</div><div class="hint">Your answers stay on this device. You’ll see what fits, why it was chosen, and which products still need checking.</div>`;
  return `<div class="flow-layout"><aside class="flow-aside"><p class="eyebrow">Your everyday, edited</p><h2>A kit that starts<br>with you.</h2><p>Small steps. Thoughtful choices.<br>And plenty of room to be yourself.</p><ol class="steps">${stepLabels.map((l,i)=>`<li><button data-step="${i}" class="${i===step?'current':i<step?'done':''}" ${i>step?'disabled':''}><span class="num">${i<step?'✓':i+1}</span>${l}</button></li>`).join('')}</ol></aside><section class="flow-card"><div class="mobile-progress"><div class="row between"><span>${stepLabels[step]}</span><span>${step+1} of 7</span></div><div class="progress-track"><div style="width:${(step+1)/7*100}%"></div></div></div><p class="eyebrow">${String(step+1).padStart(2,'0')} / A little about you</p>${content}<p class="form-error" id="form-error" role="alert"></p><div class="flow-actions"><button class="text-btn" ${step===0?'data-nav="home"':`data-step="${step-1}"`}>${icon('back')} ${step===0?'Save & close':'Back'}</button><button class="btn" data-next>${step===6?'Build my kit':'Continue'} ${icon('arrow')}</button></div></section></div>`;
}
function requirementSelect(value,label){const selected=draft.mandatoryRequirements.includes(value)?'required':draft.preferredRequirements.includes(value)?'preferred':'none';return `<label class="field"><span>${label}</span><select data-requirement="${value}">${[['none','No preference'],['preferred','Prefer it'],['required','Must have']].map(([v,l])=>`<option value="${v}" ${selected===v?'selected':''}>${l}</option>`).join('')}</select></label>`;}
function kit(){if(!state.profile)return `<div class="page-top"><p class="eyebrow">Made around your everyday</p><h1>Your shelf starts here.</h1></div><section class="empty">${icon('bag')}<h2>A little kit, with you in mind.</h2><p>Tell us what you like, what you already have, and what you’d like to spend. We’ll help with the rest.</p><button class="btn" data-start>Build my everyday kit ${icon('arrow')}</button></section>`;
  try {result=buildKit(state.profile,products,evidence);}catch(e){return `<section class="empty"><h2>Let’s check your answers.</h2><p>${esc(e.message)}</p><button class="btn" data-start>Edit my answers</button></section>`;}
  const items=[...result.items.filter(i=>i.product||i.owned),...state.profile.ownedSlots.filter(s=>!result.items.some(i=>i.slot===s&&i.owned)).map(slot=>({slot,owned:true,product:null}))];const missing=result.missing||[];const partial=result.status==='partial_planning_kit';const capConflict=state.profile.ownedSlots.length>state.profile.itemCap;const budget=state.profile.budgetCents;return `<div class="page-top row between wrap"><div><p class="eyebrow">Thoughtfully picked for your everyday</p><h1>Your little beauty kit.</h1><p>${partial?'A starting point, with a few things to resolve.':'A small routine, shaped around your choices.'}</p></div><div class="row wrap"><button class="text-btn" data-nav="recommendations">Selfie & quick edits</button><button class="btn secondary small" data-start>Edit my answers</button></div></div><div class="kit-layout"><div class="kit-list">${capConflict?'<div class="hint warning" style="margin:0 0 16px">Your kept products exceed your daily product limit. Increase the limit or change which products you keep to resolve this partial plan.</div>':''}${items.map((item,i)=>kitItem(item,i)).join('')}${missing.map(m=>`<div class="missing-card"><div class="row between"><h3>${slotLabel(m.slot)}</h3><span class="pill warn">Not filled</span></div><p>${esc(m.reason)}</p><button class="text-btn" data-pending="${m.slot}">See options & checks ${icon('arrow')}</button></div>`).join('')}${!items.length?'<p class="small muted" style="margin-top:20px">No products can fill your selected categories with the current constraints. Edit your answers or inspect the checks above.</p>':''}</div><aside class="kit-summary"><p class="eyebrow">Your plan at a glance</p><h2>Good choices add up.</h2><span class="pill ${partial?'warn':''}">${partial?'Partial planning kit':budget===null?'Unpriced preview':'Planning estimate'}</span><div class="cost-row"><span>New products</span><span>${money(result.totalCents)}</span></div><div class="cost-row"><span>Daily products</span><span>${result.itemCount} / ${state.profile.itemCap}</span></div><div class="cost-row"><span>Kept products</span><span>${items.filter(i=>i.owned).length} · $0.00</span></div><div class="cost-row"><span>Your fee reserve</span><span>${money(state.profile.reserveCents)}</span></div><div class="cost-row total"><span>Planned total + reserve</span><span>${money(result.totalCents+state.profile.reserveCents)}</span></div>${budget!==null?`<div class="cost-row"><span>Of your ${money(budget)} budget</span><span>${money(Math.max(0,budget-result.totalCents-state.profile.reserveCents))} left</span></div>`:''}<p class="small muted" style="margin-top:16px">Snapshot merchandise prices. ${state.profile.reserveCents?'Your reserve is not verified shipping or tax.':'Shipping and tax aren’t included.'} Check the store for current prices and stock.</p>${result.cheapestRequiredCents!=null&&missing.length?`<p class="small muted" style="margin-top:12px">Lowest eligible complete product subtotal: ${money(result.cheapestRequiredCents)}. Item and dependency limits still apply.</p>`:''}<button class="btn secondary" data-start>Adjust my plan ${icon('arrow')}</button><details><summary>How this kit was chosen</summary><p>Required categories are checked first. Verified preferences guide fit within each category. Verified fragrance-free or vegan preferences break equal-fit ties, followed by price. If the complete kit doesn’t fit, your chosen category order sets the priority. K-pop associations never add recommendation points.</p><p>${esc((result.notices||[]).join(' '))}</p></details></aside></div>`;
}
function kitItem(item,i){if(item.owned)return `<article class="kit-item owned-item"><div class="owned-symbol">${icon('check')}</div><div class="kit-copy"><p class="eyebrow">${slotLabel(item.slot)}</p><h3>Keeping your ${slotLabel(item.slot).toLowerCase()}</h3><p>Already on your shelf · $0 new spend. Counts toward your routine.</p></div></article>`;const p=item.product;const score=item.score;return `<article class="kit-item"><div class="kit-art">${productImage(p)}</div><div class="kit-copy"><p class="eyebrow">${String(i+1).padStart(2,'0')} · ${slotLabel(item.slot)}</p><p class="small" style="margin-top:0">${esc(p.brand)}</p><h3>${esc(p.product_name)}</h3><p>${score?.value==null?'A basic option selected by eligibility, verified preferences, then cost.':`Editorial fit ${Number(score.value).toFixed(1)} / 100 · ${Number(score.metadataCoverage||0).toFixed(0)}% evidence coverage for active preferences.`}</p><div class="row between"><strong class="price">${productPrice(p)}</strong><div class="row" style="margin:0"><button class="text-btn" data-detail="${p.id}" data-slot="${item.slot}">Why this?</button><button class="text-btn" data-swap="${item.slot}">Swap ${icon('arrow')}</button></div></div></div></article>`;}
function profile(){return `<div class="profile-layout"><div class="page-top"><p class="eyebrow">A little space for you</p><h1>Your beauty, your way.</h1><p>Your preferences and saved products stay on this device.</p></div><section class="profile-section"><h2>Your everyday profile</h2>${state.profile?`<dl class="review-grid"><div><dt>Budget</dt><dd>${state.profile.budgetCents===null?'Unpriced preview':money(state.profile.budgetCents)}</dd></div><div><dt>Routine</dt><dd>Up to ${state.profile.itemCap} products</dd></div><div><dt>Priorities</dt><dd>${state.profile.goals.map(g=>goalLabels[g]).join(', ')||'Open to suggestions'}</dd></div><div><dt>Skin feel</dt><dd>${skinLabels[state.profile.skinFeel]}</dd></div></dl>`:'<p>Start with a selfie, then add your goals and preferences to refine your beauty map.</p>'}<div class="row"><button class="btn small" data-start>${state.profile?'Edit my answers':'Create my profile'}</button></div></section><section class="profile-section"><h2>Your saved shelf</h2><p>${state.favorites.length} ${state.favorites.length===1?'product':'products'} saved for another look.</p><div class="row"><button class="btn secondary small" data-view-saved>See my saved products ${icon('arrow')}</button></div></section><section class="profile-section"><h2>Your saved inspiration</h2><p>${state.savedLooks.length} full looks and face-region references saved on this device.</p><div class="row"><button class="btn secondary small" data-view-saved-looks>See my saved references ${icon('arrow')}</button></div></section><section class="profile-section"><h2>Thoughtful by design.</h2><p>Your selfie is the starting point. On-device analysis maps brows, eyes, nose, cheeks, and lips, and checks visible texture and color variation when the photo is clear enough. A few suggestions appear on your photo; tap a region to explore a style, technique, and product ideas. Your answers refine the suggestions around your goals, comfort, and budget.</p><details><summary>About recommendations & product evidence</summary><p>Fit scores describe editorial preference matches, not efficacy or safety. Selected ingredient lists cannot prove an ingredient is absent. Mandatory requirements stay pending when exact formula evidence is missing. Product compatibility and personal tolerance are not guaranteed.</p><p>Catalog: ${esc(catalog.researched_on)} · Rules: 0.1 · ${products.length} products. Prices and availability aren’t live. K-pop entries distinguish a brand campaign from a product endorsement or personal use.</p></details><details><summary>Privacy & device storage</summary><p>Your answers, saved products, saved full looks and face-region references, and kit remain in local app storage. Selfies, sampled colors, visible-detail measurements, and face coordinates stay in memory for this session and can be removed any time; they are not uploaded or saved with your profile. Only color preferences you confirm are saved. No account, analytics, or backend is used. External source links open in your browser. Android backups are disabled for this app.</p></details><button class="text-btn" data-reset>Clear my local data</button></section></div>`;}
function openDialog(title,body){const dialog=$('#detail-dialog');dialog.innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="icon-btn" data-close aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;if(!dialog.open)dialog.showModal();dialog.scrollTop=0;}

function scoreTable(score){const labels={"daily_skin_feel":"Skin feel","ordered_goals":"Your goals","texture":"Texture","application_simplicity":"Simple application","finish":"Finish","chosen_color_family":"Color family","wear":"Wear","chosen_effect":"Eye effect","format":"Format","coverage":"Coverage","wear_and_texture":"Wear & texture"};return '<table class="score-table"><thead><tr><th>Preference</th><th>Weight</th><th>Fit points</th><th>Evidence</th></tr></thead><tbody>'+(score?.components||[]).map(c=>'<tr><td>'+esc(labels[c.dimension]||c.dimension)+'</td><td>'+c.weight+'</td><td>'+Number(100*c.weight*c.match/score.denominator).toFixed(1)+'</td><td>'+(c.known===1?'Reviewed':c.known>0?'Partly reviewed':'Unknown')+'</td></tr>').join('')+'</tbody></table><p>Unknown product evidence earns no fit points. The active weights total '+score.denominator+'. Scores describe preferences, not effectiveness or personal safety.</p>';}

function safeLink(url,label){try{const u=new URL(url);if(u.protocol!=='https:')return '';}catch{return '';}return `<a class="text-btn" href="${esc(url)}" rel="noopener noreferrer">${label} ${icon('external')}</a>`;}
function detail(id,slot){const p=products.find(p=>p.id===id);if(!p)return;const e=evidence[id];const photo=productImages[id];const item=result?.items.find(i=>i.product?.id===id&&(!slot||i.slot===slot));const score=item?.score;const k=p.kpop_connection;const active=score?.activeDimensions||[];openDialog('A closer look',`<div class="detail-hero"><div class="product-art art-${Number(id.split('-')[1])%4+1}">${productImage(p)}</div><div><p class="eyebrow">${esc(p.brand)}</p><h2>${esc(p.product_name)}</h2><strong>${productPrice(p)}</strong><p class="small muted">${esc(p.size)}</p></div></div>${photo?.src?`<div class="photo-credit">${safeLink(photo.sourceUrl,'Product photo source')}${photo.note?`<p>${esc(photo.note)}</p>`:''}</div>`:''}<div class="detail-section"><h3>On your shelf</h3><p>${esc(p.intended_benefit)}</p><div class="row"><span class="pill">${esc(p.category)}</span><span class="pill purple">${esc(p.budget_tier)}</span></div></div>${item?`<div class="detail-section"><h3>Why it’s in your kit</h3><p>${score?.value==null?'No active fit preferences apply to this category. This is a basic option chosen by eligibility, verified preferences, then cost.':`Editorial fit: ${Number(score.value).toFixed(1)} / 100. Active weight: ${score.denominator}. Evidence coverage for those preferences: ${Number(score.metadataCoverage).toFixed(1)}%.`}</p><p>Fills ${slotLabel(item.slot).toLowerCase()} and adds ${productPrice(p)} to your kit. Your planned product subtotal is ${money(result.totalCents)}.</p>${active.length?`<p>Active dimensions: ${esc(active.map(d=>typeof d==='string'?d.replaceAll('_',' '):d.name||d.dimension||JSON.stringify(d)).join(', '))}.</p>`:''}<details><summary>View scoring details</summary>${scoreTable(score)}</details></div>`:''}<div class="detail-section"><h3>Selected ingredients</h3><p>${esc(p.key_ingredients.length ? p.key_ingredients.join(' · ') : 'Ingredients have not yet been reviewed for this exact variant.')}</p><p style="margin-top:9px">These are key ingredients, not a complete formula. They cannot clear ingredient exclusions.</p></div><div class="detail-section"><h3>Evidence & exact product</h3><p>${esc(p.evidence_notes)}</p><p style="margin-top:10px">${esc(p.price_basis)}. Stock: ${esc(p.availability)}. Researched ${esc(p.researched_on)}.</p><p style="margin-top:10px">${esc(e?.identityVerified?'Catalog variant identified.':'Exact market or variant still needs checking.')}${e?.exactShade?' Selected catalog shade: '+esc(e.exactShade)+'.':''}</p><div class="row wrap">${safeLink(p.product_url,'View product source')}${p.ingredient_source_url!==p.product_url?safeLink(p.ingredient_source_url,'Ingredient source'):''}</div><details><summary>Reviewed preference evidence</summary>${Object.entries(e?.traits||{}).map(([dim,t])=>`<p><strong>${esc(dim.replaceAll('_',' '))}:</strong> ${esc((t.values||[]).join(', ')||'Unknown / not reviewed')} · ${esc(t.basis)} · ${esc(t.date)}<br>${esc(t.note||'')}<br>${safeLink(t.url,'Source')}</p>`).join('')||'<p>No reviewed preference traits.</p>'}</details></div>${k?`<div class="detail-section"><span class="pill pink">K-pop connection</span><h3 style="margin-top:10px">${esc(k.artist)}${k.group?' · '+esc(k.group):''}</h3><p>${esc(k.connection_summary)}</p><p style="margin-top:8px">${esc(k.relationship_type)} · ${esc(k.association_scope)} · ${esc(k.evidence_date)}. ${esc(k.status_as_of)}</p>${safeLink(k.source_url,'Campaign source')}</div>`:''}<button class="btn secondary" data-save="${p.id}">${icon('heart')}${state.favorites.includes(p.id)?'Remove from saved':'Save for later'}</button>`);}
function swapDialog(slot,pendingOnly=false){const list=products.filter(p=>evidence[p.id]?.slots.includes(slot));const evaluated=list.map(p=>{let trial;let error;try{trial=buildKit({...state.profile,swaps:{...state.profile.swaps,[slot]:p.id}},products,evidence);}catch(e){error=e.message;}const currentFilled=(result?.items||[]).filter(i=>i.owned||i.product).map(i=>i.slot);const chosen=trial?.items.find(i=>i.slot===slot&&i.product?.id===p.id);const retains=currentFilled.every(s=>trial?.items.some(i=>i.slot===s&&(i.owned||i.product)));const evaluation=evaluateProduct(p,slot,state.profile,evidence);return {p,trial,evaluation,available:!!chosen&&retains,error};});openDialog(pendingOnly?`${slotLabel(slot)} · what’s pending`:`Choose your ${slotLabel(slot).toLowerCase()}`,`<p class="small muted" style="margin-bottom:18px">Every option rechecks the whole kit, retained products, item limits, and removal needs. Swaps keep all currently filled categories.</p>${evaluated.map(({p,trial,evaluation,available,error})=>`<article class="swap-option"><div class="row between"><h3>${esc(p.brand+' · '+p.product_name)}</h3><span class="price">${productPrice(p)}</span></div><p>${evidence[p.id]?.requiresExplicitRequest?esc(evidence[p.id].explicitRequestReason||'This product needs an explicit choice before adding it.')+' ':''}${available?`New kit subtotal: ${money(trial.totalCents)}.`:esc(error||(evaluation.reasons||[]).join(' ')||'This option cannot fit the current kit, budget, and item limit.')}</p><div class="row between"><button class="text-btn" data-detail="${p.id}">Product details</button>${available?`<button class="btn small" data-choose-swap="${p.id}" data-slot="${slot}">Choose this</button>`:`<span class="pill warn">${evaluation.state==='excluded'?'Excluded':evaluation.state==='eligible'?'Doesn’t fit this kit':'Needs checking'}</span>`}</div></article>`).join('')||'<p class="small muted">No products in this catalog can fill this category yet.</p>'}`);}
function validateStep(){if(step===0&&!draft.slots.length)return 'Choose at least one product category.';if(step===1){for(const el of document.querySelectorAll('[data-money]'))if(!el.validity.valid)return 'Enter a nonnegative amount with no more than two decimal places.';if(draft.budgetCents!==null&&(!Number.isSafeInteger(draft.budgetCents)||draft.budgetCents<0))return 'Enter a valid budget in USD.';if(!Number.isSafeInteger(draft.reserveCents)||draft.reserveCents<0)return 'Enter a valid reserve.';if(draft.budgetCents!==null&&draft.reserveCents>draft.budgetCents)return 'The reserve cannot be larger than your total budget.';if(draft.budgetCents===null&&draft.reserveCents>0)return 'Add a budget to use a tax and shipping reserve.';}
 if(step===3&&(!Number.isInteger(draft.itemCap)||draft.itemCap<1||draft.itemCap>12))return 'Choose a daily product limit between 1 and 12.';if(step===4&&!['no','yes','unsure'].includes(draft.reactionHistory))return 'Choose an answer about previous reactions, including “I’m not sure” if needed.';return '';}
function render(){const page=route();selfie?.leave();const content=page==='selfie'||page==='recommendations'?selfie.render(page):page==='home'?home():page==='explore'?explore():page==='looks'?lookbook.render():page==='guides'?styleUI.render():page==='kit'?kit():page==='profile'?profile():page==='quiz'?flow():home();$('#app').innerHTML=shell(content,page);if(page==='explore')updateGrid();if(page==='looks')lookbook.updateGrid();document.title=`Dewdrop · ${page==='selfie'?'Take a selfie':page==='recommendations'?'Your beauty map':page==='profile'?'You':page==='quiz'?stepLabels[step]:page==='guides'?'Styles & routines':navs.find(n=>n[0]===page)?.[2]||'Discover'}`;}
function rerender(){const y=window.scrollY;render();window.scrollTo(0,y);}
function start(){draft=JSON.parse(JSON.stringify(state.draft||state.profile||draft));save();nav('quiz/0');}
document.addEventListener('error',event=>{const image=event.target;if(!(image instanceof HTMLImageElement)||!image.closest('.product-photo'))return;const frame=image.closest('.product-photo');frame.classList.add('is-unavailable');image.hidden=true;frame.querySelector('.product-photo-unavailable').hidden=false;},true);
document.addEventListener('error',event=>{const image=event.target;if(!(image instanceof HTMLImageElement)||!image.closest('.look-photo'))return;const frame=image.closest('.look-photo');frame.classList.add('is-unavailable');image.hidden=true;const message=frame.querySelector('.look-photo-fallback');if(message)message.hidden=false;},true);

document.addEventListener('click',event=>{const el=event.target.closest('button,a');if(!el)return;
  if(styleUI?.handleClick(el)||lookbook?.handleClick(el))return;
  if(el.hasAttribute('data-nav'))nav(el.dataset.nav);
  else if(el.hasAttribute('data-start'))start();
  else if(el.hasAttribute('data-close'))$('#detail-dialog').close();
  else if(el.hasAttribute('data-detail'))detail(el.dataset.detail,el.dataset.slot);
  else if(el.hasAttribute('data-save')){const id=el.dataset.save;state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();if($('#detail-dialog').open)detail(id);rerender();toast(state.favorites.includes(id)?'Saved to your shelf':'Removed from your saved shelf');}
  else if(el.hasAttribute('data-filter')){filter=el.dataset.filter;makeupCategory='';faceRegion='';catalogLimit=24;rerender();}
  else if(el.hasAttribute('data-browse-makeup')){filter='makeup';makeupCategory=el.dataset.browseMakeup;faceRegion='';brand='';search='';savedOnly=false;catalogLimit=24;nav('explore');}
  else if(el.hasAttribute('data-clear-catalog-filters')){makeupCategory='';faceRegion='';brand='';search='';catalogLimit=24;rerender();}
  else if(el.hasAttribute('data-more-products')){catalogLimit+=24;updateGrid();}
  else if(el.hasAttribute('data-saved-filter')){savedOnly=!savedOnly;catalogLimit=24;rerender();}
  else if(el.hasAttribute('data-view-saved')){savedOnly=true;filter='all';makeupCategory='';faceRegion='';brand='';search='';catalogLimit=24;nav('explore');}
  else if(el.hasAttribute('data-step')){save();nav('quiz/'+el.dataset.step);}
  else if(el.hasAttribute('data-next')){const error=validateStep();if(error){$('#form-error').textContent=error;return;}if(step===6){try{buildKit(draft,products,evidence);state.profile=JSON.parse(JSON.stringify(draft));state.profile.confirmedAt=new Date().toISOString();state.profile.answerProvenance=Object.entries(state.profile).filter(([field])=>!['answerProvenance','swaps'].includes(field)).map(([field,value])=>({field,value,source:'questionnaire',confirmed:true,updated_at:state.profile.confirmedAt,observation_id:null}));save();nav('kit');toast('Your everyday kit is ready to explore');}catch(e){$('#form-error').textContent=e.message;}}else{save();nav('quiz/'+(step+1));}}
  else if(el.hasAttribute('data-answer')){const field=el.dataset.answer;draft[field]=el.dataset.value;if(field==='scope'){draft.slots=draft.scope==='makeup'?['lip']:draft.scope==='both'?['cleanser','moisturizer','daytime_sunscreen','lip']:['cleanser','moisturizer','daytime_sunscreen'];draft.ownedSlots=draft.ownedSlots.filter(s=>draft.slots.includes(s)||s==='remover');draft.swaps={};}if(field==='routineTime')draft.itemCap={'3_minutes':3,'5_minutes':5,'10_minutes':7,help_start_small:3}[draft.routineTime];save();rerender();}
  else if(el.hasAttribute('data-toggle')){const field=el.dataset.toggle,value=el.dataset.value,list=draft[field]||[];if(field==='goals'&&!list.includes(value)&&list.length>=2){toast('Choose up to two priorities. Tap one again to remove it.');return;}draft[field]=list.includes(value)?list.filter(v=>v!==value):[...list,value];if(field==='slots'){draft.ownedSlots=draft.ownedSlots.filter(s=>draft.slots.includes(s)||s==='remover');delete draft.swaps[value];}save();rerender();}
  else if(el.hasAttribute('data-move')){const index=draft.slots.indexOf(el.dataset.move),to=index+Number(el.dataset.direction);if(to>=0&&to<draft.slots.length)[draft.slots[index],draft.slots[to]]=[draft.slots[to],draft.slots[index]];save();rerender();}
  else if(el.hasAttribute('data-swap'))swapDialog(el.dataset.swap);
  else if(el.hasAttribute('data-pending'))swapDialog(el.dataset.pending,true);
  else if(el.hasAttribute('data-choose-swap')){const updated={...state.profile,swaps:{...state.profile.swaps,[el.dataset.slot]:el.dataset.chooseSwap}};const trial=buildKit(updated,products,evidence);if(!trial.items.some(i=>i.slot===el.dataset.slot&&i.product?.id===el.dataset.chooseSwap)){toast('This option no longer fits. Review your kit.');return;}state.profile=updated;draft=JSON.parse(JSON.stringify(updated));save();$('#detail-dialog').close();render();toast('Kit updated. Budget and product limits rechecked.');}
  else if(el.hasAttribute('data-reset'))openDialog('Clear your local data?',`<p class="small muted">This removes your answers, planned kit, draft, saved products, and saved style references from this device.</p><div class="row" style="margin-top:22px"><button class="btn secondary" data-close>Keep my data</button><button class="btn" data-confirm-reset>Clear my data</button></div>`);
  else if(el.hasAttribute('data-confirm-reset')){selfie?.clear();state={favorites:[],savedLooks:[]};draft=newProfile();filter='all';search='';brand='';makeupCategory='';faceRegion='';savedOnly=false;catalogLimit=24;result=null;try{localStorage.removeItem(storageKey);}catch{}$('#detail-dialog').close();nav('home');toast('Your local data has been cleared');}
});
document.addEventListener('input',event=>{const el=event.target;if(el.closest('#selfie-experience'))return;if(lookbook?.handleInput(el))return;if(el.id==='search'){search=el.value;catalogLimit=24;updateGrid();return;}if(el.dataset.money){const v=el.value.trim();draft[el.dataset.money]=v===''?(el.dataset.money==='budgetCents'?null:0):Math.round(Number(v)*100);}else if(el.dataset.number)draft[el.dataset.number]=Number(el.value);else if(el.dataset.list)draft[el.dataset.list]=[...new Set(el.value.split(',').map(v=>v.trim()).filter(Boolean))];else if(el.dataset.field)draft[el.dataset.field]=el.value;save();});
document.addEventListener('change',event=>{const el=event.target;if(lookbook?.handleInput(el))return;if(el.id==='brand-filter'){brand=el.value;catalogLimit=24;updateGrid();return;}if(el.id==='makeup-category'){makeupCategory=el.value;catalogLimit=24;rerender();return;}if(el.id==='face-region'){faceRegion=el.value;catalogLimit=24;rerender();return;}if(el.dataset.field){draft[el.dataset.field]=el.value;save();if(el.dataset.field==='country')rerender();}if(el.dataset.boolean){draft[el.dataset.boolean]=el.checked;save();}if(el.dataset.requirement){const value=el.dataset.requirement;draft.mandatoryRequirements=draft.mandatoryRequirements.filter(x=>x!==value);draft.preferredRequirements=draft.preferredRequirements.filter(x=>x!==value);if(el.value==='required')draft.mandatoryRequirements.push(value);if(el.value==='preferred')draft.preferredRequirements.push(value);save();}if(el.id==='reaction-product'&&el.value){if(!draft.reactedProductIds.includes(el.value))draft.reactedProductIds.push(el.value);save();rerender();}if(el.dataset.shade){if(el.checked)draft.selectedShades[el.dataset.shade]=evidence[el.dataset.shade].exactShade;else delete draft.selectedShades[el.dataset.shade];save();}});
$('#detail-dialog').addEventListener('click',e=>{if(e.target===$('#detail-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
window.addEventListener('hashchange',()=>{if(!selfie)return;if($('#detail-dialog').open)$('#detail-dialog').close();render();window.scrollTo(0,0);});

export async function initializeApp({ signal } = {}) {
  const responses = await Promise.all(['catalog', 'evidence', 'product-images', 'kpop-looks', 'beauty-styles'].map(name =>
    fetch(`data/${name}.json`, { signal })));
  if (responses.some(response => !response.ok)) throw new Error('A bundled catalog file could not be loaded.');
  [catalog, evidence, productImages, styleLibrary, styleGuides] = await Promise.all(responses.map(response => response.json()));
  // Startup may have timed out while an asset was being read.
  if (signal?.aborted) throw new DOMException('Startup cancelled.', 'AbortError');
  products = catalog.products;
  state.savedLooks = validSavedLooks(state.savedLooks, styleLibrary);
  lookbook = createLookbook({library:styleLibrary,products,styleGuides,getSaved:()=>state.savedLooks,setSaved:items=>{state.savedLooks=items;save();},nav,render,toast,esc,icon,safeLink,productCard});
  styleUI = createStyleGuideUI({data:styleGuides,library:styleLibrary,products,evidence,getProfile:()=>state.profile||draft,applyGuide:(guide,kind)=>{const next=applyStyleGuide(state.profile||draft,guide,kind);state.profile=next;draft=structuredClone(next);result=null;save();render();toast(guide.title+' preferences applied');},nav,render,esc,icon,productCard,productImage});
  selfie = createSelfieExperience({getProfile:()=>state.profile||state.draft,setProfile:profile=>{state.profile=profile;result=null;draft=JSON.parse(JSON.stringify(profile));save();},products,evidence,styleGuides,lookbook:styleLibrary,render,nav,toast,esc,icon,productImage,goalLabels,skinLabels,slotLabel});
  render();
}
